const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function button(text,action,extra='',classes=''){return `<button type="button" class="btn ${classes}" data-action="${action}" ${extra}>${text}</button>`;}
function settings(){return `<div class="settings"><label>再生速度 <select data-speed aria-label="재생 속도"><option value="1">1× 기본</option><option value="4">0.25× 관찰</option></select></label><label><input type="checkbox" data-reduced>동작 줄이기 체험</label></div>`.replace('再生速度','재생 속도');}
function motionTools(){return `<div class="motion-tools">${button('재생','play')}${button('일시정지','pause')}${button('다시 보기','replay')}${button('초기화','reset')}</div>${settings()}<p class="feedback" data-motion-status role="status">사용자 동작으로 한 번 재생합니다.</p>`;}
function preview(mode='object'){return `<div class="creative-preview" data-preview data-mode="${mode}" data-entrance><div class="preview-top"><span>FRAME / STUDY 001</span><span>4:5</span></div><div class="sculpture" aria-hidden="true"></div><div class="preview-title" data-preview-title>Beyond<br>the ordinary.<small>SHAPE EXPLORATION</small></div><span class="preview-caption">직접 만든 CSS 조형물 · 외부 이미지 없음</span></div>`;}
function modeTabs(){return `<div class="row" role="tablist" aria-label="창작 작업"><button class="tab" type="button" role="tab" data-mode="object" aria-selected="true" tabindex="0">오브젝트</button><button class="tab" type="button" role="tab" data-mode="poster" aria-selected="false" tabindex="-1">포스터</button></div>`;}
function processControls(){return `<div class="row spread"><span class="meta" data-job-status role="status">대기 · 준비 완료</span>${button('생성 시작 ↗','generate','','primary')}</div><div class="progress-track" role="img" aria-label="로컬 처리 진행 상태"><div class="progress-fill" data-progress></div></div>`;}
function reviewDialog(t,key){return `<dialog aria-labelledby="review-${t.id}-${key}"><div class="stack"><span class="eyebrow">LOCAL REVIEW</span><h4 id="review-${t.id}-${key}">${t.id==='dark-ai'?'다음 장면을 위한 검토':'작업 내용 확인'}</h4><p data-review-content>${t.id==='dark-ai'?'오브젝트 · FRAME / STUDY 001 · 로컬 미리보기':'Orbit 웹사이트 개편 · 히어로 프로토타입'}</p><p class="muted">샘플 데이터로 체험합니다. 저장하거나 전송하지 않습니다.</p><div class="row">${button('검토 완료','confirm','','primary')}${button('취소','close')}</div></div></dialog>`;}
export function markup(t,key){
 if(key==='theme')return ['hero',...elementsFor(t).map(e=>e.id)].map(k=>`<section class="demo" data-theme="${t.id}" data-demo-key="${k}">${markup(t,k)}</section>`).join('<br>');
 if(t.id==='light-project')return projectMarkup(t,key);
 const controls=`<div class="floating-controls" data-entrance>${modeTabs()}<div class="row spread control-divider"><span class="meta">FRAME ENGINE / v.01</span><span class="badge">HD · 1024</span></div>${processControls()}</div>`;
 if(key==='hero')return `<div class="ai-scene"><nav class="frame-nav row spread" aria-label="창작 실험실"><span class="brand"><i aria-hidden="true"></i>FRAME<span class="muted"> / lab</span></span><span class="badge">LOCAL DEMO</span>${button('결과 검토','open')}</nav><div class="ai-body"><div class="ai-intro"><div class="hero-heading"><span class="intro-pill">A SMALL SPACE FOR BIG IDEAS</span><h3>작은 생각을,<br><em>다음 장면으로.</em></h3><p>가능성을 고르고, 형태를 조정하고.<br>당신의 아이디어가 장면이 되는 곳.</p></div><form class="hero-compose" novalidate><label>무엇을 만들어 볼까요?<textarea data-input minlength="8" maxlength="120" placeholder="빛을 머금은 파란 고리 조형물" aria-describedby="hero-feedback">빛을 머금은 파란 고리 조형물</textarea></label><div class="row spread"><span class="meta">로컬 시뮬레이션</span><button class="btn primary" type="submit">지시 적용 ↗</button></div><p id="hero-feedback" class="feedback" data-feedback role="status"></p></form><div class="ai-foot"><div><strong>01 → ∞</strong><span>작은 선택, 새로운 방향</span></div><div><strong>100% local</strong><span>서버 없이 체험하는 창작 흐름</span></div></div></div><div class="workbench"><div class="bench-top"><span class="meta">CREATIVE WORKSPACE</span><span class="badge" data-phase-badge><i class="status-dot"></i>준비됨</span></div><div class="layer-back" data-entrance>PROJECT / SHAPE STUDY<br>컨텍스트 · 빛 / 금속 / 궤도</div>${preview()}${controls}<div class="row control-divider">${button('재생','play')}${button('일시정지','pause')}${button('초기화','reset')}</div><p class="feedback" data-motion-status role="status">작업을 고르고 생성 시작을 눌러보세요.</p>${settings()}</div></div>${reviewDialog(t,key)}<p class="feedback pad" data-result role="status"></p></div>`;
 if(key==='layers')return `<div class="pad"><div class="ai-stage"><div class="layer-back" data-entrance>CONTEXT / 3 LAYERS<br>뒤쪽 패널 → 결과 → 제어부</div>${preview()}<div class="floating-controls" data-entrance><div class="row spread"><span class="meta">COMPOSITION / 01</span><span class="badge">앞쪽 제어 레이어</span></div></div></div>${motionTools()}</div>`;
 if(key==='controls')return `<div class="pad stack"><div class="control-preview"><div class="stack"><span class="eyebrow">CONTROL → OUTPUT</span><h4>하나의 형태,<br>두 개의 쓰임.</h4>${modeTabs()}<p class="muted" data-mode-description>오브젝트 · 조형물을 중심에 배치합니다.</p>${button('선택 초기화','reset')}</div>${preview()}</div>${settings()}<p class="feedback" data-motion-status role="status">탭을 바꾸면 미리보기 구성이 바뀝니다.</p></div>`;
 if(key==='process')return `<div class="pad stack"><div class="row spread"><span class="eyebrow">LOCAL RENDER QUEUE</span><span class="run-number" data-run-count>01</span></div><h4>아이디어를 장면으로.</h4>${processControls()}<div class="steps">${['입력 준비','형태 구성','결과 검토'].map((x,i)=>`<div class="step" data-step>0${i+1}<br>${x}</div>`).join('')}</div>${motionTools()}</div>`;
 if(key==='beam')return `<div class="pad stack"><span class="eyebrow">A SIGNAL, NOT A SPECTACLE</span><div class="beam-grid">${['구도','조명','질감'].map((x,i)=>`<button type="button" class="beam-tile" data-beam="${i}" aria-pressed="${i===0}">${x}<span>0${i+1} / SELECT</span></button>`).join('')}</div><div class="row">${button('선택한 빛 다시 보기','beam-replay')}${button('상태 확인','toggle','aria-pressed="false" data-state-target')}${button('사용 불가','none','disabled')}</div><label>버튼 상태 비교<select data-state-select><option value="default">기본</option><option value="hover">hover</option><option value="focus">focus</option><option value="active">active</option><option value="disabled">disabled</option></select></label>${motionTools()}</div>`;
 if(key==='prompt')return `<form class="pad stack" novalidate><span class="eyebrow">WRITE A DIRECTION</span><h4>다음 장면을 설명해 주세요.</h4><label>작업 지시<textarea data-input minlength="8" maxlength="120" placeholder="8자 이상으로 형태와 조명을 설명하세요" aria-describedby="prompt-feedback"></textarea></label><div class="row"><button class="btn primary" type="submit">지시 확인</button><button class="btn" type="reset">입력 초기화</button></div><p id="prompt-feedback" class="feedback" data-feedback role="status">8–120자 · 브라우저 안에서만 확인합니다.</p>${settings()}</form>`;
 if(key==='dialog')return `<div class="pad stack"><span class="eyebrow">PAUSE TO REVIEW</span><h4>열기부터 닫기까지,<br>하나의 짧은 전환.</h4><p class="muted">내용 확인 후 완료하거나 Esc로 돌아오세요.</p>${button('결과 검토 열기','open','','primary')}${reviewDialog(t,key)}<p class="feedback" data-result role="status">아직 검토하지 않았습니다.</p>${settings()}</div>`;
 return '';
}
function projectMarkup(t,key){
 const initialTotal=t.data.tasks.length,initialDone=t.data.tasks.filter(x=>x.status==='done').length,initialPercent=Math.round(initialDone/initialTotal*100);
 const filters=`<div class="row" role="group" aria-label="작업 상태 필터">${[['all','전체'],['active','진행·검토 중'],['done','완료']].map(([id,x])=>`<button type="button" class="chip" data-filter="${id}" aria-pressed="${id==='all'}">${x}</button>`).join('')}</div>`;
 const metrics=`<div class="metrics"><div><span>선택 범위 작업</span><strong data-metric="total">${initialTotal}</strong><small>같은 목록에서 계산</small></div><div><span>완료한 작업</span><strong data-metric="done">${initialDone}</strong><small data-metric="percent">완료율 ${initialPercent}%</small></div><div><span>진행·검토 중</span><strong data-metric="active">${initialTotal-initialDone}</strong><small>Orbit · 샘플 프로젝트</small></div></div>`;
 const taskList=`<div class="task-list" data-task-list aria-label="프로젝트 작업 목록"></div>`;
 const detail=`<div class="task-detail" data-task-detail aria-live="polite"></div>`;
 const chart=`<div class="row spread"><h4>마감일별 작업</h4><div class="row" role="tablist" aria-label="차트 표시 기간"><button type="button" class="tab" role="tab" data-period="week" aria-selected="true" tabindex="0">주간</button><button type="button" class="tab" role="tab" data-period="cumulative" aria-selected="false" tabindex="-1">누적</button></div></div><div class="bar-chart" data-chart aria-hidden="true"></div><div class="chart-values" data-chart-values role="status"></div>`;
 const calendar=`<div class="row spread"><h4>10월 일정</h4><span class="meta">2026 / OCT</span></div><div class="date-grid" role="group" aria-label="마감 날짜 선택">${t.data.dates.map((date,i)=>`<button class="date-button" type="button" data-date="${date}" aria-pressed="${i===0}"><small>${['금','토','일','월'][i]}</small>${date}<i aria-hidden="true"></i></button>`).join('')}</div><div class="agenda-list" data-agenda aria-live="polite"></div>`;
 const form=`<form class="stack" novalidate><label>새 작업 제목<input data-input type="text" minlength="3" maxlength="40" placeholder="예: 모바일 QA 확인" aria-describedby="add-feedback-${key}"></label><div class="row"><button class="btn primary" type="submit">로컬 작업 추가 +</button><button class="btn" type="reset">입력 초기화</button></div><p id="add-feedback-${key}" class="feedback" data-feedback role="status">3–40자 · 19일 일정에 추가 · 서버 저장 없음</p></form>`;
 if(key==='hero')return `<div class="project-scene"><nav class="project-nav row spread" aria-label="프로젝트 내비게이션"><span class="brand"><i aria-hidden="true"></i>Orbit<span class="muted"> / team</span></span><div class="row">${[['overview','개요'],['tasks','작업'],['calendar','일정']].map(([id,x],i)=>`<button type="button" class="tab" data-view="${id}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><span class="avatar" aria-label="샘플 담당자 서윤">SY</span></nav><div class="dashboard"><div class="dash-heading row spread"><div><span class="eyebrow">WORKSPACE / ORBIT</span><h3>좋은 아침이에요, 서윤님.</h3><p class="muted">웹사이트 개편의 다음 한 걸음.</p></div><span class="badge">샘플 데이터 · 로컬</span></div><div class="row spread dash-toolbar"><strong>프로젝트 개요</strong>${filters}</div>${metrics}<div class="dashboard-grid"><section class="module chart-module" data-dash-chart>${chart}</section><section class="module progress-module"><span class="eyebrow">TEAM MOMENTUM</span><div class="row spread"><h4>작업 통계</h4><span class="badge">LIVE SAMPLE</span></div><div class="completion-number" data-metric="percent-big">33<small>%</small></div><div class="completion-track"><div data-completion></div></div><p class="muted" data-summary></p><div class="project-file"><span class="file-icon" aria-hidden="true">↗</span><div><strong>Orbit 리디자인</strong><small>디자인 · 개발 · 검토</small></div></div></section><section class="module agenda-module" data-dash-calendar>${calendar}</section><section class="module tasks-module" data-dash-tasks><div class="row spread"><h4>팀 작업</h4><span class="meta" data-list-count>6 TASKS</span></div><div class="task-head"><span>작업 / 담당자</span><span>마감 · 상태</span></div>${taskList}${detail}</section><section class="module meeting-module"><span class="eyebrow">NEXT CHECKPOINT</span><h4>프로토타입 리뷰</h4><p>10월 19일 · 14:00</p><div class="row"><span class="avatar">SY</span><span class="avatar">JH</span><span class="avatar">MS</span></div><p class="muted">같은 목표, 서로 다른 관점.<br>다음 리뷰 전에 선택한 작업을 확인하세요.</p>${button('선택 작업 검토','open','','primary')}<details><summary>팀의 검토 기준</summary><p>키보드, 반응형, 상태 피드백을 함께 확인합니다.</p></details></section></div><div class="dash-footer row spread"><span class="meta">샘플 작업 6개 · 서버 통신 없음</span>${button('화면 초기화','reset')}</div>${settings()}<p class="feedback" data-motion-status role="status">필터·행·날짜·차트 탭을 눌러보세요.</p>${reviewDialog(t,key)}<p class="feedback" data-result role="status"></p></div></div>`;
 if(key==='tasks')return `<div class="pad stack"><div class="row spread"><span class="eyebrow">SELECT → INSPECT</span><span class="badge">Orbit</span></div>${taskList}${detail}${motionTools()}</div>`;
 if(key==='filters')return `<div class="pad stack">${filters}${metrics}${taskList}${motionTools()}</div>`;
 if(key==='chart')return `<div class="pad stack">${chart}${filters}${motionTools()}</div>`;
 if(key==='calendar')return `<div class="pad stack">${calendar}${motionTools()}</div>`;
 if(key==='quick-add')return `<div class="pad stack"><span class="eyebrow">ONE SOURCE OF TASK DATA</span><h4>작은 업무를 더해보세요.</h4>${form}${metrics}${taskList}${motionTools()}</div>`;
 if(key==='dialog')return `<div class="pad stack"><span class="eyebrow">REVIEW BEFORE YOU CONTINUE</span><h4>선택한 업무를 확인합니다.</h4>${taskList}${button('선택 작업 검토 열기','open','','primary')}${reviewDialog(t,key)}<p class="feedback" data-result role="status">샘플 작업 선택 → 검토 열기</p>${motionTools()}</div>`;
 return '';
}
// Closure-free: the same behavior is embedded in every standalone export.
export function wireDemo(root,t){
 const controller=new AbortController(),signal=controller.signal;const listen=(el,event,fn)=>el?.addEventListener(event,fn,{signal});
 const osReduced=matchMedia('(prefers-reduced-motion: reduce)'),animations=new Map();let userPaused=false,visible=true,generation=0,job='idle',jobAnimation=null,mode='object',opener=null,closing=false;
 const reduced=()=>osReduced.matches||!!root.querySelector('[data-reduced]')?.checked;
 const speed=()=>Number(root.querySelector('[data-speed]')?.value||1);
 const say=text=>{const p=root.querySelector('[data-motion-status]');if(p)p.textContent=text;};
 function inView(el){const r=el.getBoundingClientRect();return r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth;}
 function animate(el,frames,duration=t.motion.duration,delay=0){if(!el||reduced()||(userPaused&&el.tagName!=='DIALOG'))return null;cancelTarget(el);const a=el.animate(frames,{duration:duration*speed(),delay:delay*speed(),easing:t.motion.ease,fill:'backwards'});animations.set(el,a);targetObserver.observe(el);if(!inView(el)||document.hidden||(userPaused&&el.tagName!=='DIALOG'))a.pause();const release=()=>{if(animations.get(el)===a){animations.delete(el);targetObserver.unobserve(el);}};a.finished.then(release,release);return a;}
 function enter(el,duration=t.motion.duration,delay=0){cancelTarget(el);const base=el?getComputedStyle(el).transform:'none';return animate(el,[{opacity:0,transform:`translateY(${t.motion.y}px) scale(${t.motion.scale}) ${base==='none'?'':base}`},{opacity:1,transform:base}],duration,delay);}
 function cancelTarget(el){animations.get(el)?.cancel();animations.delete(el);if(el)targetObserver.unobserve(el);}
 function cancelAll(){generation++;animations.forEach((a,el)=>{a.cancel();targetObserver.unobserve(el);});animations.clear();jobAnimation=null;}
 function resume(){userPaused=false;animations.forEach((a,el)=>{if(inView(el)&&!document.hidden)a.play();});say('재생 중 · 화면 밖에서는 정지합니다.');}
 function setJob(next){job=next;root.dataset.job=next;const phase=root.querySelector('[data-phase-badge]');if(phase)phase.textContent=next==='running'?'처리 중':next==='done'?'완료':'준비됨';const label=root.querySelector('[data-job-status]');if(label)label.textContent=next==='running'?'처리 중 · 로컬 시뮬레이션':next==='done'?'완료 · 결과를 검토하세요':'대기 · 준비 완료';root.querySelectorAll('[data-action=generate]').forEach(b=>{b.disabled=next==='running';b.textContent=next==='done'?'다시 생성 ↗':'생성 시작 ↗';});root.querySelectorAll('[data-step]').forEach(x=>x.dataset.done=String(next==='done'));const bar=root.querySelector('[data-progress]');if(bar)bar.style.transform=next==='done'?'scaleX(1)':'scaleX(0)';}
 function generate(){if(job==='running')return;cancelAll();userPaused=false;setJob('running');const version=generation;const bar=root.querySelector('[data-progress]');jobAnimation=animate(bar,[{transform:'scaleX(0)'},{transform:'scaleX(1)'}],t.motion.records.process.duration);const done=()=>{if(!signal.aborted&&version===generation&&job==='running'){setJob('done');say('완료 · 네트워크 요청 없이 만든 로컬 상태입니다.');}};if(jobAnimation)jobAnimation.finished.then(done,()=>{});else done();}
 function selectMode(value){mode=value;root.querySelectorAll('[data-mode]').forEach(b=>{const yes=b.dataset.mode===value;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1;});root.querySelectorAll('[data-preview]').forEach(p=>{p.dataset.mode=value;p.setAttribute('aria-label',value==='object'?'파란 고리 조형물 오브젝트 미리보기':'파란 고리 조형물 포스터 미리보기');if(!root.querySelector('[role=tablist]'))p.setAttribute('role','img');enter(p,t.motion.records.controls.duration);});const desc=root.querySelector('[data-mode-description]');if(desc)desc.textContent=value==='object'?'오브젝트 · 조형물을 중심에 배치합니다.':'포스터 · 조형물 위에 큰 제목의 위계를 더합니다.';say(value==='object'?'오브젝트 작업 선택':'포스터 작업 선택');}
 function beam(value){root.querySelectorAll('[data-beam]').forEach(b=>{cancelTarget(b);b.setAttribute('aria-pressed',String(b.dataset.beam===String(value)));if(b.dataset.beam===String(value))animate(b,[{boxShadow:'0 0 0px #82ACFF00'},{boxShadow:'0 0 28px '+t.material.beam,offset:.45},{boxShadow:'0 0 0px #82ACFF00'}],t.motion.records.beam.duration);});say('선택된 제어부에 한 번 빛이 나타납니다.');}
 function play(restart=false){if(t.id==='light-project'){if(root.dataset.demoKey==='dialog'){open(root.querySelector('[data-action=open]'));return;}if(!restart&&userPaused){resume();return;}cancelAll();userPaused=false;projectRender(root.dataset.demoKey||'filters');say(reduced()?'동작 줄이기 · 최종 상태':'선택한 데이터를 다시 재생합니다.');return;}if(!restart&&userPaused){resume();return;}const key=root.dataset.demoKey;if(key==='hero'&&job==='running'){resume();return;}if(key==='process'){if(restart){cancelAll();setJob('idle');}generate();return;}if(key==='beam'){cancelAll();userPaused=false;beam(root.querySelector('[data-beam][aria-pressed=true]')?.dataset.beam||0);return;}cancelAll();userPaused=false;root.querySelectorAll('[data-entrance]').forEach((el,i)=>enter(el,t.motion.records.layers.duration,i*t.motion.records.layers.delay));say(reduced()?'동작 줄이기 · 최종 상태를 즉시 표시합니다.':'등장 재생 · 뒤 레이어부터 앞 레이어 순서.');}
 function reset(){if(t.id==='light-project'){projectReset();return;}cancelAll();userPaused=false;setJob('idle');selectMode('object');cancelAll();const selector=root.querySelector('[data-state-select]');if(selector)selector.value='default';const state=root.querySelector('[data-state-target]');if(state){state.disabled=false;state.removeAttribute('data-state');state.setAttribute('aria-pressed','false');state.textContent='상태 확인';}const f=root.querySelector('form');f?.reset();root.querySelectorAll('[data-beam]').forEach((x,i)=>x.setAttribute('aria-pressed',String(i===0)));say('초기화 완료 · 콘텐츠는 최종 배치로 보입니다.');}
 let tasks=t.data?structuredClone(t.data.tasks):[],filter='all',selected=tasks[1]?.id,date=t.data?.dates[0]||16,period='week';
 const filtered=()=>tasks.filter(x=>filter==='all'||(filter==='done'?x.status==='done':x.status!=='done'));
 const statusName=x=>({done:'완료',active:'진행 중',review:'검토 중'}[x]);
 const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function projectRender(kind='none'){
  if(t.id!=='light-project')return;if(kind!=='none')cancelAll();const list=filtered();if(!list.some(x=>x.id===selected))selected=list[0]?.id;const current=list.find(x=>x.id===selected);const done=list.filter(x=>x.status==='done').length,total=list.length,percent=total?Math.round(done/total*100):0;
  root.querySelectorAll('[data-metric]').forEach(p=>{const key=p.dataset.metric;if(key==='percent-big'){p.innerHTML=percent+'<small>%</small>';return;}p.textContent=key==='total'?total:key==='done'?done:key==='active'?total-done:key==='percent'?'완료율 '+percent+'%':percent+'%';});
  const completion=root.querySelector('[data-completion]');if(completion)completion.style.width=percent+'%';const summary=root.querySelector('[data-summary]');if(summary)summary.textContent=`${total}개 중 ${done}개 완료 · ${total-done}개 진행/검토`;
  root.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));
  const rows=list.map(x=>`<button type="button" class="task-row" data-task="${x.id}" aria-pressed="${x.id===selected}"><span class="task-main"><span class="avatar" aria-hidden="true">${safe(x.initial)}</span><span><strong>${safe(x.title)}</strong><small>${safe(x.owner)} · ${safe(x.category)}</small></span></span><span class="task-end"><span>10.${x.date}</span><span class="task-status" data-status="${x.status}">${statusName(x.status)}</span></span></button>`).join('');
  root.querySelectorAll('[data-task-list]').forEach(p=>p.innerHTML=rows||'<p class="empty">조건에 맞는 작업이 없습니다.</p>');
  const count=root.querySelector('[data-list-count]');if(count)count.textContent=total+' TASKS';const detail=root.querySelector('[data-task-detail]');if(detail)detail.innerHTML=current?`<span class="meta">${safe(current.id)} / SELECTED TASK</span><h5>${safe(current.title)}</h5><p>${safe(current.detail)}</p><p>${safe(current.owner)} · 10월 ${current.date}일 · ${statusName(current.status)}</p>`:'<p>선택할 작업이 없습니다.</p>';
  let sum=0;const values=t.data.dates.map(d=>{const n=list.filter(x=>x.date===d).length;sum+=n;return period==='week'?n:sum;});const max=Math.max(...values,1);const chart=root.querySelector('[data-chart]');if(chart)chart.innerHTML=values.map(v=>`<div class="bar-column"><i class="chart-bar ${v===max?'is-max':''}" style="height:${Math.round(v/max*100)}%"></i></div>`).join('');
  const text=root.querySelector('[data-chart-values]');if(text)text.innerHTML=values.map((v,i)=>`<span>10.${t.data.dates[i]} / ${v}개</span>`).join('');
  root.querySelectorAll('[data-period]').forEach(b=>{const yes=b.dataset.period===period;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1;});
  root.querySelectorAll('[data-date]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.date)===date)));const agenda=root.querySelector('[data-agenda]');if(agenda){const scheduled=list.filter(x=>x.date===date);agenda.innerHTML=`<span class="meta">10월 ${date}일 · ${scheduled.length}개 일정</span>`+scheduled.map(x=>`<div class="agenda-item"><strong>${safe(x.title)}</strong><small>${safe(x.owner)} · ${statusName(x.status)}</small></div>`).join('')+(scheduled.length?'':'<p class="empty">선택 범위에 일정이 없습니다.</p>');}
  const review=root.querySelector('[data-review-content]');if(review)review.textContent=current?`${current.title} · ${current.owner} · 10월 ${current.date}일 · ${statusName(current.status)}`:'선택한 작업이 없습니다.';
  if(kind==='tasks')enter(detail,t.motion.records.tasks.duration);if(kind==='filters'||kind==='quick-add')root.querySelectorAll('[data-task-list]').forEach(el=>enter(el,t.motion.records[kind].duration));if(kind==='chart'||kind==='filters'){root.querySelectorAll('.chart-bar').forEach((bar,i)=>animate(bar,[{transform:'scaleY(0)'},{transform:'scaleY(1)'}],t.motion.records.chart.duration,i*t.motion.records.chart.delay));}if(kind==='calendar')enter(agenda,t.motion.records.calendar.duration);
 }
 function projectReset(){cancelAll();userPaused=false;tasks=structuredClone(t.data.tasks);filter='all';selected=tasks[1]?.id;date=t.data.dates[0];period='week';root.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view==='overview')));projectRender();root.querySelector('form')?.reset();say('초기화 완료 · 원래 샘플 데이터로 돌아왔습니다.');}
 if(t.id==='light-project')projectRender();
 const dialog=root.querySelector('dialog');
 function open(button){if(!dialog||dialog.open)return;opener=button;closing=false;const p=dialog.querySelector('[data-review-content]');if(t.id==='dark-ai'&&p)p.textContent=`${mode==='object'?'오브젝트':'포스터'} · FRAME / STUDY 001 · ${job==='done'?'생성 완료':'미리보기 검토'}`;dialog.showModal();enter(dialog,t.motion.records.dialog.duration);dialog.querySelector('button')?.focus();}
 function close(){if(!dialog?.open||closing)return;closing=true;const a=animate(dialog,[{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:`translateY(${t.motion.y}px) scale(${t.motion.scale})`}],t.motion.close);const done=()=>{if(!signal.aborted){dialog.close();closing=false;opener?.focus();}};if(a)a.finished.then(done,done);else done();}
 listen(dialog,'cancel',e=>{e.preventDefault();close();});listen(dialog,'click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 listen(root,'click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.task){selected=b.dataset.task;projectRender('tasks');root.querySelector('[data-task="'+selected+'"]')?.focus({preventScroll:true});say('작업 상세를 갱신했습니다.');}if(b.dataset.filter){filter=b.dataset.filter;projectRender('filters');say('필터와 지표·차트·목록을 함께 갱신했습니다.');}if(b.dataset.period){period=b.dataset.period;projectRender('chart');say(period==='week'?'마감일별 주간 분포':'같은 작업의 마감일별 누적 분포');}if(b.dataset.date){date=Number(b.dataset.date);projectRender('calendar');say('10월 '+date+'일 일정 선택');}if(b.dataset.view){root.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const target=root.querySelector(b.dataset.view==='tasks'?'[data-dash-tasks]':b.dataset.view==='calendar'?'[data-dash-calendar]':'.dash-heading');target?.scrollIntoView({behavior:'auto',block:'nearest'});if(target){target.tabIndex=-1;target.focus({preventScroll:true});}}if(b.dataset.mode)selectMode(b.dataset.mode);if(b.dataset.beam!==undefined)beam(b.dataset.beam);const a=b.dataset.action;if(a==='generate')generate();if(a==='play')play();if(a==='replay')play(true);if(a==='pause'){userPaused=true;animations.forEach(x=>x.pause());say('일시정지 · 재생으로 이어보세요.');}if(a==='reset')reset();if(a==='open')open(b);if(a==='close')close();if(a==='confirm'){const p=root.querySelector('[data-result]');if(p)p.textContent='검토 완료 · 로컬 체험이며 저장/전송하지 않았습니다.';close();}if(a==='beam-replay')beam(root.querySelector('[data-beam][aria-pressed=true]')?.dataset.beam||0);if(a==='toggle'){const yes=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'선택됨':'상태 확인';}});
 root.querySelectorAll('[role=tablist]').forEach(group=>listen(group,'keydown',e=>{const tabs=[...group.querySelectorAll('[role=tab]')];let i=tabs.indexOf(e.target);if(i<0)return;if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();tabs[i].click();tabs[i].focus();}));
 listen(root.querySelector('[data-state-select]'),'change',e=>{const b=root.querySelector('[data-state-target]');b.dataset.state=e.target.value;b.disabled=e.target.value==='disabled';});
 const form=root.querySelector('form'),input=form?.querySelector('[data-input]'),feedback=form?.querySelector('[data-feedback]');
 listen(form,'submit',e=>{e.preventDefault();const value=input.value.trim();if(t.id==='light-project'){const ok=value.length>=3&&value.length<=40&&!tasks.some(x=>x.title===value);input.setAttribute('aria-invalid',String(!ok));input.dataset.valid=String(ok);feedback.dataset.tone=ok?'success':'error';if(!ok){feedback.textContent='입력 오류 · 3–40자의 중복되지 않는 제목을 입력하세요.';input.focus();return;}const id='L-'+(tasks.length+1);tasks.push({id,title:value,owner:'나',initial:'ME',status:'active',date:19,category:'로컬 추가',detail:'이 체험에서 추가한 작업입니다. 서버에 저장하지 않습니다.'});filter='all';selected=id;date=19;projectRender('quick-add');feedback.textContent='추가 완료 · 19일 일정과 지표에 반영했습니다. 서버 저장 없음.';return;}const ok=value.length>=8&&value.length<=120;input.setAttribute('aria-invalid',String(!ok));input.dataset.valid=String(ok);feedback.dataset.tone=ok?'success':'error';feedback.textContent=ok?'지시 확인 완료 · 브라우저 안에서만 반영했습니다.':'입력 오류 · 8–120자로 장면을 설명해 주세요.';if(!ok)input.focus();else enter(feedback,t.motion.records.prompt.duration);});
 listen(input,'input',()=>{input.removeAttribute('aria-invalid');delete input.dataset.valid;feedback.removeAttribute('data-tone');feedback.textContent='입력 후 지시 확인을 눌러주세요.';});listen(form,'reset',()=>{input.removeAttribute('aria-invalid');delete input.dataset.valid;feedback.removeAttribute('data-tone');feedback.textContent=t.id==='light-project'?'3–40자 · 19일 일정에 추가 · 서버 저장 없음':'8–120자 · 브라우저 안에서만 확인합니다.';});
 function applyReduced(){root.dataset.reduced=String(reduced());if(reduced()){const running=job==='running';cancelAll();if(running)setJob('done');say('동작 줄이기 · 이동 없이 최종 상태를 표시합니다.');}}
 listen(root.querySelector('[data-reduced]'),'change',applyReduced);listen(osReduced,'change',applyReduced);
 const targetObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{const a=animations.get(entry.target);if(!a)return;if(!entry.isIntersecting||document.hidden||(userPaused&&entry.target.tagName!=='DIALOG'))a.pause();else a.play();}),{threshold:0});
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible)animations.forEach((a,el)=>{if(el.tagName!=='DIALOG')a.pause();});else if(!document.hidden&&!userPaused)animations.forEach((a,el)=>{if(inView(el)&&(!userPaused||el.tagName==='DIALOG'))a.play();});});observer.observe(root);
 listen(document,'visibilitychange',()=>{if(document.hidden)animations.forEach((a,el)=>{if(closing&&el===dialog)a.finish();else a.pause();});else if(visible)animations.forEach((a,el)=>{if(inView(el)&&(!userPaused||el.tagName==='DIALOG'))a.play();});});
 const unique='ui-'+Math.random().toString(36).slice(2);
 if(input&&feedback){feedback.id=unique+'-feedback';input.setAttribute('aria-describedby',feedback.id);}
 if(dialog){const title=dialog.querySelector('h4');title.id=unique+'-review';dialog.setAttribute('aria-labelledby',title.id);}
 root.querySelectorAll('[role=tablist]').forEach((group,i)=>{const tabs=[...group.querySelectorAll('[role=tab]')],panel=group.querySelector('[data-period]')?root.querySelector('[data-chart-values]'):root.querySelector('[data-preview]');if(!panel)return;panel.id=unique+'-panel-'+i;panel.setAttribute('role','tabpanel');panel.tabIndex=0;tabs.forEach((tab,j)=>{tab.id=unique+'-tab-'+i+'-'+j;tab.setAttribute('aria-controls',panel.id);});panel.setAttribute('aria-labelledby',tabs.find(x=>x.getAttribute('aria-selected')==='true').id);listen(group,'click',e=>{const tab=e.target.closest('[role=tab]');if(tab)panel.setAttribute('aria-labelledby',tab.id);});});
 applyReduced();return ()=>{controller.abort();cancelAll();observer.disconnect();targetObserver.disconnect();if(dialog?.open)dialog.close();};
}
export function standalone(t,key){const safeJSON=x=>JSON.stringify(x).replace(/</g,'\\u003c');const html=key==='theme'?markup(t,'theme'):`<main class="demo" data-theme="${t.id}" data-demo-key="${key}">${markup(t,key)}</main>`;return `<!doctype html>\n<html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(t.name)} / ${escapeHTML(key)}</title><style>body{margin:0;padding:16px;background:${t.colors.background}}main,body>section{max-width:${t.layout.max}px;margin:auto}${demoCSS(t)}</style><body>${html}<script>/* 완전한 단일 HTML. 외부 의존성/통신 없음. 로컬 샘플 상태만 사용. */\nconst theme=${safeJSON(t)};\ndocument.querySelectorAll('.demo').forEach(root=>(${wireDemo.toString()})(root,theme));<\/script></body></html>`;}
